app.get('/api/supabase/status', async (_req, res) => {
  const cfg = getSupabaseConfig();
  if (!cfg) {
    return res.json({
      configured: false,
      connected: false,
      tableReady: false,
      projectName: SUPABASE_PROJECT_LABEL,
      tableName: SUPABASE_TABLE,
