      // Ignore URL cleanup errors
    }

    handleSyncHistoryWithCloud();

    const onWindowFocus = () => {
      if (document.visibilityState === 'visible') {
        handleSyncHistoryWithCloud();
      }
    };
    window.addEventListener('focus', onWindowFocus);
    window.addEventListener('visibilitychange', onWindowFocus);
