const EXAMPLE_ALARMS = [
  'Está sinalizando no supervisório baixa pressão de óleo na UHLM',
  'Falta de tensão 125Vcc no CSG2',
  'Fusível queimado na folha 4',
  'Bloqueio de fechamento do disjuntor 52G1 por intertravamento na chave 89-5',
];

export const FaultQueryPanel: React.FC<FaultQueryPanelProps> = ({
  query,
  setQuery,
  activeFocusTopic,
  setActiveFocusTopic,
  onRunDiagnosis,
  isAnalyzing,
  hasPreviousTurns,
}) => {
  const [isListeningVoice, setIsListeningVoice] = useState(false);
  const [isTranscribingAudio, setIsTranscribingAudio] = useState(false);
  const [voiceAudioLevel, setVoiceAudioLevel] = useState(0);
  const [voiceElapsedSec, setVoiceElapsedSec] = useState(0);
  const [voiceStatusMessage, setVoiceStatusMessage] = useState<string | null>(
    null
  );
  const audioFileInputRef = useRef<HTMLInputElement | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);

  const queryRef = useRef<string>(query);
  queryRef.current = query;
  const setQueryRef = useRef(setQuery);
  setQueryRef.current = setQuery;

  const voiceEngineRef = useRef<UniversalVoiceDictation | null>(null);

  useEffect(() => {
    const engine = new UniversalVoiceDictation({
      getInitialText: () => queryRef.current,
      onTextUpdate: (fullText) => {
        queryRef.current = fullText;
        setQueryRef.current(fullText);
      },
      onStateChange: (st) => {
        setIsListeningVoice(st.isRecording);
        setIsTranscribingAudio(st.isTranscribing);
        setVoiceAudioLevel(st.audioLevel);
        setVoiceElapsedSec(st.elapsedSeconds);
        setVoiceStatusMessage(st.statusMessage);
      },
    });
    voiceEngineRef.current = engine;
    return () => {
      engine.destroy();
    };
  }, []);

  const toggleVoiceQuery = async () => {
    const engine = voiceEngineRef.current;
    if (!engine) return;
    if (engine.getIsRecording()) {
      await engine.stop();
      setTimeout(() => textareaRef.current?.focus(), 40);
    } else if (!engine.getIsTranscribing()) {
      await engine.start();
    }
  };

  const handleAudioFileUpload = async (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file = e.target.files?.[0];
    if (!file) return;
    e.target.value = '';
    setIsTranscribingAudio(true);
    setVoiceStatusMessage(`⏳ Transcrevendo arquivo de áudio "${file.name}"...`);
    try {
      const transcript = await requestAudioTranscription(
        file,
        file.type || 'audio/webm'
      );
      if (transcript) {
        const nextText = [queryRef.current.trim(), transcript]
          .filter(Boolean)
          .join(' ')
          .trim();
        queryRef.current = nextText;
        setQuery(nextText);
        setVoiceStatusMessage('✅ Áudio transcrito com sucesso!');
        setTimeout(() => setVoiceStatusMessage(null), 3500);
      } else {
        setVoiceStatusMessage(
          '⚠️ Não foi possível identificar fala no arquivo de áudio enviado.'
        );
      }
    } catch {
      setVoiceStatusMessage(
        '⚠️ Erro ao transcrever o arquivo de áudio enviado.'
      );
    } finally {
      setIsTranscribingAudio(false);
    }
  };

  const formatTimer = (sec: number) => {
    const m = String(Math.floor(sec / 60)).padStart(2, '0');
    const s = String(sec % 60).padStart(2, '0');
    return `${m}:${s}`;
  };

  const handleQuickButtonClick = async (btn: QuickSupportButtonConfig) => {
    if (isAnalyzing) return;

    const isSameFocus = activeFocusTopic === btn.focusPrompt;
    const nextFocus = isSameFocus ? '' : btn.focusPrompt;
    setActiveFocusTopic(nextFocus);

    // If user already typed an alarm or already has an active diagnostic session,
    // clicking a quick support button triggers the focused analysis immediately
    if ((query.trim().length > 0 || hasPreviousTurns) && !isSameFocus) {
      await onRunDiagnosis(btn.focusPrompt);
    } else if (!query.trim()) {
      setQuery(btn.label);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isAnalyzing) return;
    if (voiceEngineRef.current?.getIsRecording()) {
      await voiceEngineRef.current.stop();
    }
    await onRunDiagnosis();
  };

  return (
    <section
      aria-label="Caixa de Consulta de Falha ou Alarme"
      className="bg-[#111827] border border-slate-800 rounded-lg p-4 flex flex-col gap-3"
    >
      <input
        ref={audioFileInputRef}
        type="file"
        accept="audio/*,.ogg,.mp3,.wav,.m4a,.webm"
        onChange={handleAudioFileUpload}
        className="hidden"
      />

      <div>
        <h2 className="text-sm font-semibold text-slate-100">
          2. Consulta de Falha / Alarme
        </h2>
        <p className="text-[11px] text-slate-400 mt-0.5">
          Descreva ou dite por voz o alarme do supervisório (SCADA) ou sintoma
          em campo
        </p>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-3">
        <div className="flex flex-col gap-1.5">
          <div className="text-xs font-medium text-slate-300 flex items-center justify-between gap-2 flex-wrap">
            <label htmlFor="fault-query-input">Alarme ou Sintoma</label>
            <div className="flex items-center gap-1.5">
              <button
                type="button"
                disabled={isTranscribingAudio}
                onClick={toggleVoiceQuery}
                className={`px-2.5 py-1 rounded text-[11px] font-semibold flex items-center gap-1.5 cursor-pointer border transition-colors ${
                  isListeningVoice
                    ? 'bg-rose-600 hover:bg-rose-500 text-white border-rose-400 animate-pulse shadow-sm'
                    : isTranscribingAudio
                      ? 'bg-amber-600/30 text-amber-200 border-amber-500/40 animate-pulse'
                      : 'bg-sky-500/15 hover:bg-sky-500/25 text-sky-300 border-sky-500/40'
                }`}
                title="Ditar alarme ou sintoma por voz no microfone (Português)"
              >
                {isListeningVoice ? (
                  <>
                    <MicOff className="w-3.5 h-3.5" />
                    <span>Concluir Voz ({formatTimer(voiceElapsedSec)})</span>
                  </>
                ) : isTranscribingAudio ? (
                  <span>⏳ Transcrevendo...</span>
                ) : (
                  <>
                    <Mic className="w-3.5 h-3.5 text-sky-400" />
                    <span>Ditar por Voz</span>
                  </>
                )}
              </button>

              {query && (
                <button
                  type="button"
                  onClick={() => {
                    setQuery('');
                    queryRef.current = '';
                    voiceEngineRef.current?.updateBaseTextFromManualEdit('');
                    setActiveFocusTopic('');
                  }}
                  className="text-[11px] text-slate-400 hover:text-slate-200 flex items-center gap-1 cursor-pointer"
                >
                  <RotateCcw className="w-3 h-3" />
                  <span>Limpar</span>
                </button>
              )}
            </div>
          </div>

          {/* Barra Interativa de Status do Microfone / Medidor de Voz no PC */}
          {(isListeningVoice || isTranscribingAudio || voiceStatusMessage) && (
            <div
              className={`p-2.5 rounded-md border text-[11px] flex flex-col gap-2 ${
                voiceStatusMessage?.startsWith('⚠️')
                  ? 'bg-amber-950/70 border-amber-500/50 text-amber-200'
                  : isListeningVoice
                    ? 'bg-rose-950/60 border-rose-500/50 text-rose-100'
                    : 'bg-sky-950/60 border-sky-500/40 text-sky-200'
              }`}
            >
              <div className="flex items-center justify-between gap-2">
                <div className="flex items-center gap-2 min-w-0">
                  {isListeningVoice && (
                    <span className="w-2.5 h-2.5 rounded-full bg-rose-500 animate-ping shrink-0" />
                  )}
                  <span className="font-medium leading-snug">
                    {voiceStatusMessage ||
                      (isListeningVoice
                        ? `🎙️ Gravando (${formatTimer(voiceElapsedSec)}) — Fale agora...`
                        : '⏳ Transcrevendo sua fala...')}
                  </span>
                </div>

                {!isListeningVoice && !isTranscribingAudio && (
                  <button
                    type="button"
                    onClick={() => setVoiceStatusMessage(null)}
                    className="p-0.5 text-slate-400 hover:text-white shrink-0 cursor-pointer"
                    title="Fechar aviso"
                  >
                    <X className="w-3.5 h-3.5" />
                  </button>
                )}
              </div>

              {isListeningVoice && (
                <div className="flex items-center justify-between gap-2">
                  <div className="flex-1 h-2 bg-slate-900 rounded-full overflow-hidden border border-slate-700">
                    <div
                      className="h-full bg-emerald-400 transition-all duration-75"
                      style={{
                        width: `${Math.min(100, Math.max(10, voiceAudioLevel))}%`,
                      }}
                    />
                  </div>
                  <button
                    type="button"
                    onClick={toggleVoiceQuery}
                    className="px-2.5 py-1 rounded bg-rose-600 hover:bg-rose-500 text-white font-bold text-[10px] shrink-0 cursor-pointer"
                  >
                    Parar e Transcrever
                  </button>
                </div>
              )}

              {voiceStatusMessage?.startsWith('⚠️') && (
                <div className="flex items-center justify-between gap-2 pt-1 border-t border-amber-500/30">
                  <span className="text-[10px] text-amber-300/90">
                    Sem microfone no PC? Você também pode enviar um áudio gravado (ex: WhatsApp):
                  </span>
                  <button
                    type="button"
                    onClick={() => audioFileInputRef.current?.click()}
                    className="px-2.5 py-1 rounded bg-amber-500/25 hover:bg-amber-500/40 border border-amber-400/50 text-amber-100 font-semibold text-[11px] flex items-center gap-1 shrink-0 cursor-pointer"
                  >
                    <FileAudio className="w-3 h-3" />
                    <span>Enviar Áudio</span>
                  </button>
                </div>
              )}
            </div>
          )}

          <textarea
            ref={textareaRef}
            id="fault-query-input"
            rows={2}
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              queryRef.current = e.target.value;
              voiceEngineRef.current?.updateBaseTextFromManualEdit(
                e.target.value
              );
            }}
            placeholder='Ex: "Baixa pressão de óleo na UHLM", "Falta de tensão 125Vcc no CSG2"...'
            className="w-full bg-[#0B111E] border border-slate-700 focus:border-sky-500 rounded-md p-2.5 text-xs sm:text-sm text-slate-100 placeholder:text-slate-500 focus:outline-none transition-colors resize-y"
          />
        </div>

        {/* Example quick-fill prompts */}
        <div className="flex flex-col gap-1">
          <span className="text-[11px] text-slate-400">
            Exemplos rápidos (clique para preencher):
          </span>
          <div className="flex flex-wrap gap-1">
            {EXAMPLE_ALARMS.map((example) => (
              <button
                key={example}
                type="button"
                onClick={() => setQuery(example)}
                className="text-left text-[11px] text-slate-300 hover:text-sky-300 bg-[#0B111E] hover:bg-slate-800/90 border border-slate-800 hover:border-slate-700 rounded px-2 py-0.5 transition-colors cursor-pointer truncate max-w-full"
              >
                &quot;{example}&quot;
              </button>
            ))}
          </div>
        </div>

        {/* 4 Mandatory Quick Support Buttons in Compact 2x2 Grid */}
        <div className="flex flex-col gap-1.5 pt-1 border-t border-slate-800/80">
          <span className="text-[11px] font-medium text-slate-300">
            Foco Técnico Rápido:
          </span>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5">
            {QUICK_SUPPORT_BUTTONS.map((btn) => {
              const isSelected = activeFocusTopic === btn.focusPrompt;
              return (
                <button
                  key={btn.id}
                  type="button"
                  disabled={isAnalyzing}
                  onClick={() => handleQuickButtonClick(btn)}
                  title={btn.label}
                  className={`w-full text-left px-2.5 py-2 rounded-md border text-xs font-medium transition-colors flex items-center gap-2 cursor-pointer disabled:opacity-50 ${
                    isSelected
                      ? 'bg-sky-500/15 border-sky-500/50 text-sky-200'
                      : 'bg-[#0B111E] border-slate-800 hover:border-slate-700 text-slate-200 hover:bg-slate-800/70'
                  }`}
                >
                  {btn.icon}
                  <span className="truncate text-[11px]">{btn.label}</span>
                </button>
              );
            })}
          </div>
        </div>

        <button
          type="submit"
          disabled={isAnalyzing || (!query.trim() && !activeFocusTopic)}
          className="w-full py-2.5 px-4 bg-sky-600 hover:bg-sky-500 disabled:bg-slate-800 disabled:text-slate-500 text-white font-medium text-xs rounded-md transition-colors flex items-center justify-center gap-2 cursor-pointer whitespace-nowrap shrink-0"
        >
          <Send className="w-3.5 h-3.5" />
          <span>
            {isAnalyzing
              ? 'Varrendo Diagramas (/EL, /RB, /ME, /RM)...'
              : hasPreviousTurns
                ? 'Executar Nova Consulta na Sequência'
                : 'Executar Diagnóstico Eletromecânico'}
          </span>
        </button>
      </form>
    </section>
  );
};

