function inferCategoryFromFilename(filename: string): DiagramCategoryTag {
  const upper = filename.toUpperCase();
  if (upper.includes('RB') || upper.includes('BORNE')) return '/RB';
  if (upper.includes('ME') || upper.includes('MECANIC')) return '/ME';
  if (
    upper.includes('RM') ||
    upper.includes('MATERIA') ||
    upper.includes('LISTA')
  )
    return '/RM';
  if (
    upper.endsWith('.JPG') ||
    upper.endsWith('.JPEG') ||
    upper.endsWith('.PNG') ||
    upper.endsWith('.WEBP')
  ) {
    return 'FOTO CAMPO';
  }
  return '/EL';
}

function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result as string;
      const base64 = result.includes(',') ? result.split(',')[1] : result;
      resolve(base64);
    };
    reader.onerror = (err) => reject(err);
    reader.readAsDataURL(file);
  });
}

async function normalizeImageForChat(file: File): Promise<{
  base64: string;
  mimeType: string;
  previewDataUrl: string;
}> {
  const rawBase64 = await fileToBase64(file);
  const rawMime = file.type && file.type.startsWith('image/') ? file.type : 'image/jpeg';
  const rawDataUrl = `data:${rawMime};base64,${rawBase64}`;

  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      try {
        const maxDim = 1600;
        let width = img.naturalWidth || img.width || 1200;
        let height = img.naturalHeight || img.height || 900;

        if (width > maxDim || height > maxDim) {
          if (width >= height) {
            height = Math.round((height * maxDim) / width);
            width = maxDim;
          } else {
            width = Math.round((width * maxDim) / height);
            height = maxDim;
          }
        }

        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (!ctx) {
          resolve({
            base64: rawBase64,
            mimeType: rawMime,
            previewDataUrl: rawDataUrl,
          });
          return;
        }
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, width, height);
        ctx.drawImage(img, 0, 0, width, height);

        const compressedDataUrl = canvas.toDataURL('image/jpeg', 0.86);
        const compressedBase64 = compressedDataUrl.includes(',')
          ? compressedDataUrl.split(',')[1]
          : rawBase64;
        resolve({
          base64: compressedBase64,
          mimeType: 'image/jpeg',
          previewDataUrl: compressedDataUrl,
        });
      } catch {
        resolve({
          base64: rawBase64,
          mimeType: rawMime,
          previewDataUrl: rawDataUrl,
        });
      }
    };
    img.onerror = () => {
      resolve({
        base64: rawBase64,
        mimeType: rawMime,
        previewDataUrl: rawDataUrl,
      });
    };
    img.src = rawDataUrl;
  });
}

export const FaultChatPanel: React.FC<FaultChatPanelProps> = ({
  alarmTitle,
  messages,
  onSendMessage,
  isSending,
  chatProgressStep,
  onOpenSequenceUpload,
  onOpenPdfDeepLink,
  fillHeight = false,
}) => {
  const [inputText, setInputText] = useState('');
  const [attachedFile, setAttachedFile] =
    useState<ChatAttachmentPayload | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [isPlusMenuOpen, setIsPlusMenuOpen] = useState(false);
  const [isDraggingOver, setIsDraggingOver] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(
    () => messages.length === 0
  );
  const [isListeningVoice, setIsListeningVoice] = useState(false);
  const [isTranscribingAudio, setIsTranscribingAudio] = useState(false);
  const [voiceAudioLevel, setVoiceAudioLevel] = useState(0);
  const [voiceElapsedSec, setVoiceElapsedSec] = useState(0);
  const [voiceStatusText, setVoiceStatusText] = useState<string | null>(null);
  const [autoSpeakEnabled, setAutoSpeakEnabled] = useState<boolean>(() => {
    try {
      return localStorage.getItem('hydrodiag_auto_speak_v1') === 'true';
    } catch {
      return false;
    }
  });
  const [activeSpeakingId, setActiveSpeakingId] = useState<string | null>(null);
  const usedMicInLastTurnRef = useRef<boolean>(false);
  const lastSpokenMessageIdRef = useRef<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const cameraInputRef = useRef<HTMLInputElement | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const plusMenuRef = useRef<HTMLDivElement | null>(null);
  const chatEndRef = useRef<HTMLDivElement | null>(null);
  const inputTextRef = useRef<string>('');
  inputTextRef.current = inputText;

  const voiceEngineRef = useRef<UniversalVoiceDictation | null>(null);

  useEffect(() => {
    const unsubSpeech = technicalSpeechEngine.subscribe((st) => {
      setActiveSpeakingId(st.isSpeaking ? st.activeId : null);
    });
    return () => {
      unsubSpeech();
    };
  }, []);

  // Initialize lastSpokenMessageIdRef with existing messages on mount so we only auto-speak NEW replies
  useEffect(() => {
    if (messages.length > 0 && !lastSpokenMessageIdRef.current) {
      lastSpokenMessageIdRef.current = messages[messages.length - 1].id;
    }
  }, []);

  // Auto-speak newest assistant response when autoSpeakEnabled is on OR user used microphone
  useEffect(() => {
    if (isSending || messages.length === 0) return;
    const lastMsg = messages[messages.length - 1];
    if (
      lastMsg.role === 'assistant' &&
      lastMsg.id !== lastSpokenMessageIdRef.current
    ) {
      lastSpokenMessageIdRef.current = lastMsg.id;
      if (autoSpeakEnabled || usedMicInLastTurnRef.current) {
        usedMicInLastTurnRef.current = false;
        technicalSpeechEngine.speak(lastMsg.id, lastMsg.content);
      }
    }
  }, [messages, isSending, autoSpeakEnabled]);

  const handleToggleAutoSpeak = () => {
    setAutoSpeakEnabled((prev) => {
      const next = !prev;
      try {
        localStorage.setItem('hydrodiag_auto_speak_v1', String(next));
      } catch {
        // Ignore storage error
      }
      if (!next && activeSpeakingId) {
        technicalSpeechEngine.stop();
      }
      return next;
    });
  };

  useEffect(() => {
    const engine = new UniversalVoiceDictation({
      getInitialText: () => inputTextRef.current,
      onTextUpdate: (fullText) => {
        setInputText(fullText);
        inputTextRef.current = fullText;
      },
      onStateChange: (st) => {
        setIsListeningVoice(st.isRecording);
        setIsTranscribingAudio(st.isTranscribing);
        setVoiceAudioLevel(st.audioLevel);
        setVoiceElapsedSec(st.elapsedSeconds);
        setVoiceStatusText(st.statusMessage);
      },
    });
    voiceEngineRef.current = engine;
    return () => {
      engine.destroy();
    };
  }, []);

  const toggleChatVoiceDictation = async () => {
    const engine = voiceEngineRef.current;
    if (!engine) return;
    if (engine.getIsRecording()) {
      usedMicInLastTurnRef.current = true;
      await engine.stop();
      setTimeout(() => textareaRef.current?.focus(), 40);
    } else if (!engine.getIsTranscribing()) {
      // Stop any ongoing speech synthesis before listening to user's microphone
      technicalSpeechEngine.stop();
      usedMicInLastTurnRef.current = true;
      await engine.start();
    }
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        plusMenuRef.current &&
        !plusMenuRef.current.contains(event.target as Node)
      ) {
        setIsPlusMenuOpen(false);
      }
    };
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape' || event.key === 'Esc') {
        setIsPlusMenuOpen(false);
      }
    };
    if (isPlusMenuOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      window.addEventListener('keydown', handleKeyDown, true);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      window.removeEventListener('keydown', handleKeyDown, true);
    };
  }, [isPlusMenuOpen]);

  const processSelectedFile = async (file: File) => {
    try {
      const isPdf =
        file.type === 'application/pdf' ||
        file.name.toLowerCase().endsWith('.pdf');

      if (isPdf) {
        const base64 = await fileToBase64(file);
        const defaultCategory = inferCategoryFromFilename(file.name);
        setAttachedFile({
          base64,
          mimeType: 'application/pdf',
          name: file.name || 'desenho_anexado.pdf',
          sizeBytes: file.size,
          categoryTag: defaultCategory,
          panelName: '',
        });
      } else {
        const { base64, mimeType, previewDataUrl } =
          await normalizeImageForChat(file);
        setAttachedFile({
          base64,
          mimeType,
          name: file.name || `foto_campo_${Date.now()}.jpg`,
          sizeBytes: file.size,
          categoryTag: 'FOTO CAMPO',
          panelName: '',
          previewDataUrl,
        });
      }
      setTimeout(() => {
        textareaRef.current?.focus();
      }, 40);
    } catch {
      // Ignore file read error
    }
  };

  const triggerFilePicker = (accept: string) => {
    setIsPlusMenuOpen(false);
    if (fileInputRef.current) {
      fileInputRef.current.accept = accept;
      fileInputRef.current.value = '';
      fileInputRef.current.click();
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    await processSelectedFile(file);
    e.target.value = '';
  };

  const handlePaste = async (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
    const items = e.clipboardData?.items;
    if (!items) return;
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      if (item.kind === 'file') {
        const file = item.getAsFile();
        if (file) {
          e.preventDefault();
          await processSelectedFile(file);
          return;
        }
      }
    }
  };

  const handleDrop = async (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDraggingOver(false);
    const file = e.dataTransfer?.files?.[0];
    if (file) {
      await processSelectedFile(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSending || isTranscribingAudio) return;

    let currentText = inputText.trim();
    if (voiceEngineRef.current?.getIsRecording()) {
      const transcribed = await voiceEngineRef.current.stop();
      if (transcribed && transcribed.trim()) {
        currentText = transcribed.trim();
      }
    }

    if (!currentText && !attachedFile) return;

    const isPdf = attachedFile?.mimeType === 'application/pdf';
    const defaultPrompt = isPdf
      ? `Anexei o novo caderno PDF "${attachedFile?.name}"${
          attachedFile?.panelName ? ` (Painel ${attachedFile.panelName})` : ''
        } para continuarmos a investigação desta falha. Analise este diagrama em conjunto com o contexto atual.`
      : 'Analise esta foto de medição/campo anexada em relação à falha atual.';

    const textToSend = currentText || defaultPrompt;
    const fileToSend = attachedFile || undefined;

    setInputText('');
    inputTextRef.current = '';
    setAttachedFile(null);
    setIsPlusMenuOpen(false);

    await onSendMessage(textToSend, fileToSend);
    setTimeout(() => {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
    }, 100);
  };

  const handleSuggestionClick = async (suggestion: string) => {
    if (isSending) return;
    const fileToSend = attachedFile || undefined;
    setAttachedFile(null);
    setShowSuggestions(false);
    await onSendMessage(suggestion, fileToSend);
    setTimeout(() => {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
    }, 100);
  };

  const handleCopy = async (msg: FaultChatMessage) => {
    try {
      await navigator.clipboard.writeText(formatTechnicalSymbols(msg.content));
      setCopiedId(msg.id);
      setTimeout(() => setCopiedId(null), 2000);
    } catch {
      // Ignore
    }
  };

  return (
    <div
      className={`bg-[#0B111E] flex flex-col no-print ${
        fillHeight
          ? 'h-full min-h-0 flex-1'
          : 'mt-4 border border-sky-500/30 rounded-lg'
      }`}
    >
      {/* Header */}
      <div
        className={`px-4 py-2.5 bg-slate-900/90 border-b border-slate-800 flex flex-wrap items-center justify-between gap-2 shrink-0 ${
          fillHeight ? '' : 'rounded-t-lg'
        }`}
      >
        <div className="flex items-center gap-2.5 min-w-0">
          <div className="w-7 h-7 rounded-md bg-sky-500/15 border border-sky-500/30 flex items-center justify-center text-sky-400 shrink-0">
            <MessageSquare className="w-4 h-4" />
          </div>
          <div className="min-w-0">
            <h3 className="text-xs sm:text-sm font-semibold text-slate-100 truncate">
              Eng. Eletricista Sênior — Chat Técnico em Tempo Real
            </h3>
            <p className="text-[11px] text-slate-400 truncate">
              Alarme:{' '}
              <span className="text-sky-300 font-medium">
                &quot;{alarmTitle}&quot;
              </span>{' '}
              · Botão <strong>+</strong> anexa PDF ou Foto
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <button
            type="button"
            onClick={handleToggleAutoSpeak}
            className={`px-2.5 py-1 rounded text-[11px] font-medium border flex items-center gap-1.5 cursor-pointer transition-colors ${
              autoSpeakEnabled
                ? 'bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-200 border-emerald-500/40'
                : 'bg-slate-800 hover:bg-slate-700 text-slate-300 border-slate-700'
            }`}
            title="Ativar leitura automática em voz alta das respostas do especialista (Modo Mãos-Livres para uso com multímetro no painel)"
          >
            {autoSpeakEnabled ? (
              <Volume2 className="w-3.5 h-3.5 text-emerald-400 animate-pulse" />
            ) : (
              <VolumeX className="w-3.5 h-3.5 text-slate-400" />
            )}
            <span>
              {autoSpeakEnabled ? 'Voz Auto: ON' : 'Voz Mãos-Livres'}
            </span>
          </button>

          <button
            type="button"
            onClick={() => setShowSuggestions((prev) => !prev)}
            className="px-2.5 py-1 rounded text-[11px] font-medium bg-slate-800 hover:bg-slate-700 text-sky-300 border border-slate-700 flex items-center gap-1 cursor-pointer transition-colors"
          >
            <Sparkles className="w-3 h-3 text-sky-400" />
            <span>Perguntas Rápidas</span>
            {showSuggestions ? (
              <ChevronUp className="w-3 h-3" />
            ) : (
              <ChevronDown className="w-3 h-3" />
            )}
          </button>

          <span className="text-[11px] font-mono tabular-nums text-slate-400">
            {messages.length} msg
          </span>
        </div>
      </div>

      {/* Collapsible Tactical 1-Click Field Suggestions */}
      {showSuggestions && (
        <div className="px-4 py-2.5 bg-[#111827]/80 border-b border-slate-800/80 flex flex-col gap-1.5 shrink-0">
          <div className="flex items-center justify-between text-[11px] font-medium text-sky-300">
            <span>
              Perguntas Rápidas de Bancada e Campo (clique para enviar):
            </span>
            <button
              type="button"
              onClick={() => setShowSuggestions(false)}
              className="text-slate-400 hover:text-slate-200 text-[10px] cursor-pointer"
            >
              Ocultar
            </button>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5 max-h-36 overflow-y-auto pr-1">
            {TACTICAL_CHAT_SUGGESTIONS.map((sug) => (
              <button
                key={sug}
                type="button"
                disabled={isSending}
                onClick={() => handleSuggestionClick(sug)}
                className="text-left text-[11px] text-slate-300 hover:text-sky-200 bg-[#0B111E] hover:bg-sky-500/15 border border-slate-800 hover:border-sky-500/40 rounded px-2.5 py-1.5 transition-colors cursor-pointer disabled:opacity-50 line-clamp-2"
              >
                {sug}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Conversation History Stream */}
      <div
        className={`p-4 flex flex-col gap-4 overflow-y-auto ${
          fillHeight ? 'flex-1 min-h-0' : 'max-h-[520px]'
        }`}
      >
        {messages.length === 0 && !isSending ? (
          <div className="py-6 text-center space-y-2">
            <p className="text-xs text-slate-300 font-medium">
              Tem alguma dúvida específica sobre um borne, relé, folha complementar ou resultado do multímetro?
            </p>
            <p className="text-xs text-slate-400 max-w-xl mx-auto">
              Use o botão <strong>+</strong> na barra abaixo para anexar um novo
              PDF elétrico ou foto tirada em campo, ou digite sua pergunta
              diretamente.
            </p>
          </div>
        ) : (
          messages.map((msg) => {
            const isUser = msg.role === 'user';
            return (
              <div
                key={msg.id}
                className={`flex flex-col gap-1.5 ${
                  isUser ? 'items-end' : 'items-start'
                }`}
              >
                <div
                  className={`max-w-3xl w-full rounded-lg p-4 border ${
                    isUser
                      ? 'bg-sky-950/30 border-sky-800/60 text-slate-100 ml-auto sm:w-auto sm:min-w-[320px]'
                      : 'bg-[#111827] border-slate-800 text-slate-200'
                  }`}
                >
                  <div className="flex items-center justify-between gap-4 border-b border-slate-800/80 pb-2 mb-2.5 text-xs text-slate-400">
                    <div className="flex items-center gap-1.5 font-medium">
                      {isUser ? (
                        <>
                          <User className="w-3.5 h-3.5 text-sky-400" />
                          <span className="text-sky-300">
                            Operador / Manutenção
                          </span>
                        </>
                      ) : (
                        <>
                          <Bot className="w-3.5 h-3.5 text-emerald-400" />
                          <span className="text-emerald-300">
                            Eng. Eletricista Sênior (PCH/UHE)
                          </span>
                        </>
                      )}
                    </div>

                    <div className="flex items-center gap-2 font-mono tabular-nums text-[11px]">
                      <span>
                        {new Date(msg.timestamp).toLocaleTimeString('pt-BR', {
                          hour: '2-digit',
                          minute: '2-digit',
                        })}
                      </span>
                      {!isUser && (
                        <>
                          <button
                            type="button"
                            onClick={() =>
                              technicalSpeechEngine.toggleSpeak(
                                msg.id,
                                msg.content
                              )
                            }
                            className={`px-2 py-0.5 rounded border flex items-center gap-1 cursor-pointer transition-colors ${
                              activeSpeakingId === msg.id
                                ? 'bg-rose-500/20 border-rose-500/50 text-rose-200 animate-pulse'
                                : 'bg-slate-800/90 hover:bg-slate-700 border-slate-700 text-sky-300'
                            }`}
                            title={
                              activeSpeakingId === msg.id
                                ? 'Parar leitura em voz alta'
                                : 'Ouvir resposta em voz alta (Modo Mãos-Livres no Painel)'
                            }
                          >
                            {activeSpeakingId === msg.id ? (
