              {isListeningVoice && (
                <button
                  type="button"
                  onClick={toggleChatVoiceDictation}
                  className="px-3 py-1 rounded-lg bg-rose-600 hover:bg-rose-500 text-white font-semibold text-xs shrink-0 cursor-pointer shadow-sm"
                >
                  Concluir e Transcrever
